package app.aleatorika;
import android.graphics.*;
import android.graphics.drawable.Drawable;
/** Small monochrome outline control icons, tinted to match the button label. */
public final class ButtonIcon extends Drawable{
 private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);private final int kind,size;
 public ButtonIcon(int kind,int color,int size){this.kind=kind;this.size=size;p.setColor(color);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2.3f);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);setBounds(0,0,size,size);}
 public static int forLabel(String s){if(s.startsWith("←")||s.startsWith("♫")||s.equals("Ⅱ"))return 0;if(s.equals("Ноты"))return 1;if(s.equals("Аккорды"))return 2;if(s.contains("скорость")||s.contains("время"))return 3;if(s.contains("Обучение"))return 4;if(s.contains("Меню")||s.contains("Назад")||s.contains("Завершить")||s.contains("настройкам"))return 5;if(s.contains("Пропустить")||s.contains("Следующ"))return 6;if(s.contains("Образец")||s.contains("услышать")||s.contains("Звучит")||s.contains("Послушать"))return 1;if(s.contains("Начать")||s.contains("Продолжить"))return 7;if(s.contains("Пауза")||s.equals("Ⅱ"))return 8;return 0;}
 private void line(Canvas c,float... xy){Path path=new Path();path.moveTo(xy[0],xy[1]);for(int i=2;i<xy.length;i+=2)path.lineTo(xy[i],xy[i+1]);c.drawPath(path,p);}
 @Override public void draw(Canvas canvas){canvas.save();canvas.translate(getBounds().left,getBounds().top);canvas.scale(getBounds().width()/24f,getBounds().height()/24f);switch(kind){case 1:line(canvas,9,18,9,5,20,3,20,16);line(canvas,9,8,20,6);canvas.drawOval(3,16,9,20,p);canvas.drawOval(14,14,20,18,p);break;case 2:for(int x:new int[]{5,12,19})line(canvas,x,3,x,21);line(canvas,3,7,21,7);line(canvas,3,15,21,15);break;case 3:canvas.drawCircle(12,14,8,p);line(canvas,12,9,12,14,15,16);line(canvas,8,2,16,2);line(canvas,12,2,12,5);break;case 4:line(canvas,3,8,12,3,21,8,12,13,3,8);line(canvas,6,11,6,17,12,21,18,17,18,11);break;case 5:line(canvas,10,6,4,12,10,18);line(canvas,4,12,20,12);break;case 6:line(canvas,14,6,20,12,14,18);line(canvas,4,12,20,12);break;case 7:line(canvas,8,4,20,12,8,20,8,4);break;case 8:line(canvas,8,5,8,19);line(canvas,16,5,16,19);break;case 10:canvas.drawCircle(12,12,8.3f,p);Path q=new Path();q.moveTo(9.5f,9);q.cubicTo(10,6,15.3f,6.5f,14.5f,10);q.cubicTo(14,11.5f,12,11.4f,12,13.3f);canvas.drawPath(q,p);p.setStyle(Paint.Style.FILL);canvas.drawCircle(12,16.7f,.9f,p);p.setStyle(Paint.Style.STROKE);break;case 11:line(canvas,4,6,9,6);line(canvas,15,6,20,6);canvas.drawCircle(12,6,3,p);line(canvas,4,18,9,18);line(canvas,15,18,20,18);canvas.drawCircle(12,18,3,p);break;case 12:line(canvas,7,3,17,3,17,8);canvas.drawArc(7,3,17,13,0,180,false,p);line(canvas,7,8,7,3);line(canvas,7,5,3,5,3,8,7,11);line(canvas,17,5,21,5,21,8,17,11);line(canvas,12,13,12,20);line(canvas,8,21,16,21);break;case 13:line(canvas,6,6,18,18);line(canvas,18,6,6,18);break;case 9:Path ear=new Path();ear.moveTo(6,9);ear.cubicTo(6,0,19,0,19,9);ear.cubicTo(19,14,13,14,13,18);ear.cubicTo(13,22,7,22,7,18);ear.moveTo(10,9);ear.cubicTo(10,5,15,5,15,9);ear.cubicTo(15,11,12,11,12,14);canvas.drawPath(ear,p);break;}canvas.restore();}
 @Override public int getIntrinsicWidth(){return size;}@Override public int getIntrinsicHeight(){return size;}@Override public void setAlpha(int a){p.setAlpha(a);}@Override public void setColorFilter(ColorFilter f){p.setColorFilter(f);}@Override public int getOpacity(){return PixelFormat.TRANSLUCENT;}
}
